// Actual calloc core composed with full memory-fill/SSE2 zeroing and new-handler dispatcher. No additional address credit; lock, small pool, heap and decoder endpoints remain explicit.
using System;namespace Recovered.Gameplay {public static class PtlCallocChildrenCPU {public static uint Allocate(SoundSetupImage m,uint count,uint size,uint error,Func<SoundSetupImage,uint,uint[],uint> leaf){Func<SoundSetupImage,uint,uint[],uint> route=null;route=delegate(SoundSetupImage image,uint address,uint[] args){if(address==0x6e6950)return PtlRuntimeMemory.Fill(image,args[0],args[1],args[2]);if(address==0x6f2905)return PtlNewHandler.Invoke(image,args[0],route);return leaf(image,address,args);};return PtlCallocCore.Allocate(m,count,size,error,route);}}}